// storage.js - All data is saved to localStorage on your PC

const KEYS = {
  BULK_IDS: 'popstock_bulk_ids',
  ORDERS: 'popstock_orders',
};

const DEFAULT_BULK_IDS = [
  { id: 'BULK-001', label: 'Bulk Pack Alpha', totalStock: 5000, usedStock: 0, pricePerUnit: 0.05 },
  { id: 'BULK-002', label: 'Bulk Pack Beta', totalStock: 8000, usedStock: 0, pricePerUnit: 0.04 },
];

const DEFAULT_ORDERS = [];

export const loadBulkIds = () => {
  try {
    const data = localStorage.getItem(KEYS.BULK_IDS);
    return data ? JSON.parse(data) : DEFAULT_BULK_IDS;
  } catch {
    return DEFAULT_BULK_IDS;
  }
};

export const saveBulkIds = (bulkIds) => {
  localStorage.setItem(KEYS.BULK_IDS, JSON.stringify(bulkIds));
};

export const loadOrders = () => {
  try {
    const data = localStorage.getItem(KEYS.ORDERS);
    return data ? JSON.parse(data) : DEFAULT_ORDERS;
  } catch {
    return DEFAULT_ORDERS;
  }
};

export const saveOrders = (orders) => {
  localStorage.setItem(KEYS.ORDERS, JSON.stringify(orders));
};

export const clearAllData = () => {
  localStorage.removeItem(KEYS.BULK_IDS);
  localStorage.removeItem(KEYS.ORDERS);
};
